-- Historical daily AUD/USD and AUD/THB reference rates for the
-- /backtest page (workflow J). Sourced from RBA's own published F11.1
-- daily exchange rate series (a free downloadable CSV, not an API call
-- -- see AUDTHB-project-status.md), which is authoritative for both AUD
-- legs and needs no key or per-request quota. Separate from
-- market_prices, which holds live intraday ticks for the monitoring
-- dashboard, not a daily historical reference series.
--
-- Already applied directly against the project via the Supabase MCP
-- tool; this file documents it, same convention as this repo's other
-- migrations. The backfill below is a one-time historical load fetched
-- from https://www.rba.gov.au/statistics/tables/csv/f11.1-data.csv on
-- 2026-09-20 -- refreshing it later is a manual re-fetch + re-run, not
-- a live cron (RBA's CSV endpoint blocks plain automated HTTP clients).
create table if not exists public.backtest_daily_rates (
  rate_date date primary key,
  aud_usd numeric not null,
  aud_thb numeric not null,
  source text not null default 'RBA F11.1',
  inserted_at timestamptz not null default now()
);

alter table public.backtest_daily_rates enable row level security;

on conflict (rate_date) do update set aud_usd = excluded.aud_usd, aud_thb = excluded.aud_thb;
